package com.rotarypumpers.meraki;
import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.UUID;
final class RecipeStore {
 private final File file;
 RecipeStore(File dir){file=new File(dir,"recipes-v1.json");}
 synchronized JSONArray load()throws Exception{return file.exists()?decode(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)):new JSONArray();}
 static JSONArray decode(String text)throws Exception{JSONObject root=new JSONObject(text);if(!"rp-companion-recipes".equals(root.optString("format"))||root.optInt("version")!=1)throw new IOException("Expected a Companion recipe backup (version 1)");JSONArray list=root.getJSONArray("recipes");if(list.length()>200)throw new IOException("Maximum 200 recipes");JSONArray clean=new JSONArray();java.util.HashSet<String> ids=new java.util.HashSet<>();for(int i=0;i<list.length();i++){JSONObject r=validate(list.getJSONObject(i));if(!ids.add(r.getString("id")))throw new IOException("Duplicate recipe ID");clean.put(r);}return clean;}
 static JSONObject validate(JSONObject r)throws Exception{JSONObject o=new JSONObject();String id=r.optString("id");UUID.fromString(id);o.put("id",id);String name=r.getString("name").trim();if(name.isEmpty()||name.length()>80)throw new IOException("Recipe name must be 1–80 characters");o.put("name",name);for(String k:new String[]{"dose_g","yield_g","brew_c","grind"}){double v=r.getDouble(k);double lo=k.equals("brew_c")?40:k.equals("grind")?0:0.1;double hi=k.equals("brew_c")?110:k.equals("grind")?100:500;if(!Double.isFinite(v)||v<lo||v>hi||(k.equals("grind")&&v!=Math.floor(v)))throw new IOException("Check "+k.replace('_',' '));o.put(k,v);}if(r.has("yield_max_g")){double hi=r.getDouble("yield_max_g");if(!Double.isFinite(hi)||hi<o.getDouble("yield_g")||hi>500)throw new IOException("Yield maximum must be at least the yield minimum (up to 500 g)");o.put("yield_max_g",hi);}
 for(String k:new String[]{"time_s","time_max_s"})if(r.has(k)){double v=r.getDouble(k);if(!Double.isFinite(v)||v<0.1||v>180)throw new IOException("Extraction time must be 0.1–180 seconds");o.put(k,v);}
 if(o.has("time_max_s")&&(!o.has("time_s")||o.getDouble("time_max_s")<o.getDouble("time_s")))throw new IOException("Enter an extraction time minimum no greater than its maximum");
 if(r.has("bag_id")){String bag=r.getString("bag_id");UUID.fromString(bag);o.put("bag_id",bag);}
 if(r.has("shot_time_window")){Object flag=r.get("shot_time_window");if(!(flag instanceof Boolean))throw new IOException("Invalid shot time window switch");boolean on=r.getBoolean("shot_time_window");o.put("shot_time_window",on);if(on&&(!o.has("time_s")||!o.has("time_max_s")||o.getDouble("time_s")>=o.getDouble("time_max_s")))throw new IOException("Shot time window needs From less than To");if(!on){o.remove("time_s");o.remove("time_max_s");}}
 org.json.JSONObject home=com.rotarypumpers.meraki.core.HomeAppearance.recipe(r);if(r.has("home_color")){o.put("home_color",home.getString("color")).put("home_name",home.getString("name"));}
 if(r.has("preinfusion_mode"))o.put("preinfusion_mode",com.rotarypumpers.meraki.core.RecipePreinfusion.mode(r));
 String notes=r.optString("notes","");if(notes.length()>8000)throw new IOException("Notes exceed 8000 characters");com.rotarypumpers.meraki.core.RecipeBackground.copy(r,o);return o.put("notes",notes);}
 static String span(JSONObject r,String min,String max,String unit){double a=r.optDouble(min,Double.NaN);if(!Double.isFinite(a))return "";double b=r.optDouble(max,a);return String.format(java.util.Locale.US,b>a?"%.1f–%.1f %s":"%.1f %3$s",a,b,unit);}
 static String summary(JSONObject r){String time=com.rotarypumpers.meraki.core.ShotTimeWindow.enabled(r)?span(r,"time_s","time_max_s","s"):"";String base=String.format(java.util.Locale.US,"%.1f g → %s%s · %.1f°C · Grind %d",r.optDouble("dose_g"),String.format(java.util.Locale.US,"%.1f g",r.optDouble("yield_g")),time.isEmpty()?"":" · "+time,r.optDouble("brew_c"),r.optInt("grind"));String pi=r.optString("preinfusion_mode","keep");return base+(pi.equals("on")?" · Pre-infusion On":pi.equals("off")?" · Pre-infusion Off":"");}
 static String encode(JSONArray list)throws Exception{return new JSONObject().put("format","rp-companion-recipes").put("version",1).put("recipes",list).toString(2);}
 synchronized String exportText()throws Exception{JSONArray list=load();JSONObject root=new JSONObject(encode(list));new RecipeMediaStore(file.getParentFile()).addTo(root,list);root.put("bags",new BagStore(file.getParentFile()).load());String text=root.toString(2);if(text.getBytes(StandardCharsets.UTF_8).length>RecipeMediaStore.MAX_BACKUP_BYTES)throw new IOException("Recipe backup exceeds 32 MB");return text;}
 synchronized JSONArray importText(String text)throws Exception{if(text.getBytes(StandardCharsets.UTF_8).length>RecipeMediaStore.MAX_BACKUP_BYTES)throw new IOException("Recipe backup exceeds 32 MB");JSONArray list=decode(text);JSONObject root=new JSONObject(text);JSONArray bags=root.optJSONArray("bags");if(root.has("bags")&&bags==null)throw new IOException("Invalid bag library");if(bags!=null)BagStore.validate(bags);new RecipeMediaStore(file.getParentFile()).importFrom(root);if(bags!=null){java.util.Map<String,String> map=new BagStore(file.getParentFile()).merge(bags);for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);String mapped=map.get(r.optString("bag_id"));if(mapped!=null)r.put("bag_id",mapped);}}return merge(list);}
 synchronized void save(JSONArray list)throws Exception{String text=encode(list);decode(text);File tmp=new File(file.getParentFile(),"recipes-v1.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 synchronized JSONArray merge(JSONArray imported)throws Exception{JSONArray old=load(),result=new JSONArray(old.toString());java.util.HashSet<String> ids=new java.util.HashSet<>();for(int i=0;i<old.length();i++)ids.add(old.getJSONObject(i).getString("id"));for(int i=0;i<imported.length();i++){JSONObject r=validate(imported.getJSONObject(i));if(ids.contains(r.getString("id"))){boolean same=false;for(int j=0;j<old.length();j++)if(old.getJSONObject(j).getString("id").equals(r.getString("id"))&&old.getJSONObject(j).toString().equals(r.toString()))same=true;if(same)continue;r.put("id",UUID.randomUUID().toString());}ids.add(r.getString("id"));result.put(r);}save(result);return result;}
}
